local GlassBenchMaker = {}
local PRODUCTS = {
    iron_glassbench = { name = "Železni delovna miza za steklarje", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni delovna miza za steklarje za steklarje." },
    bronze_glassbench = { name = "Bronast delovna miza za steklarje", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast delovna miza za steklarje za steklarje." },
    silver_glassbench = { name = "Srebrn delovna miza za steklarje", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn delovna miza za steklarje za steklarje." },
    gilded_glassbench = { name = "Pozlačen delovna miza za steklarje", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen delovna miza za steklarje za steklarje." },
    jewel_set_glassbench = { name = "Draguljast delovna miza za steklarje", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast delovna miza za steklarje za steklarje." },
    royal_sovereign_glassbench = { name = "Kraljevski suveren delovna miza za steklarje", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren delovna miza za steklarje z biseri za krono." },
}
local BUILDINGS = {
    glassbench_workshop = { name = "Glassbench delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    glassbench_house = { name = "Glassbench hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_glassbench_atelier = { name = "Mojstrski glassbench atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_glassbench_palace = { name = "Suverena glassbench palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassBenchMaker.ironStock=12; GlassBenchMaker.bronzeStock=10; GlassBenchMaker.woodStock=18; GlassBenchMaker.leatherStock=8; GlassBenchMaker.silverStock=8; GlassBenchMaker.goldStock=6; GlassBenchMaker.jewelStock=4; GlassBenchMaker.pearlStock=4
GlassBenchMaker.productStock = {}; GlassBenchMaker.buildings = {}; GlassBenchMaker.maker = nil; GlassBenchMaker.activeMaking = {}; GlassBenchMaker.totalProducts = 0; GlassBenchMaker.dayTimer = 0
function GlassBenchMaker.init() GlassBenchMaker.ironStock=12; GlassBenchMaker.bronzeStock=10; GlassBenchMaker.woodStock=18; GlassBenchMaker.leatherStock=8; GlassBenchMaker.silverStock=8; GlassBenchMaker.goldStock=6; GlassBenchMaker.jewelStock=4; GlassBenchMaker.pearlStock=4; GlassBenchMaker.productStock={}; GlassBenchMaker.buildings={}; GlassBenchMaker.maker=nil; GlassBenchMaker.activeMaking={}; GlassBenchMaker.totalProducts=0; GlassBenchMaker.dayTimer=0; print("[GlassBenchMaker] Royal Glass Bench Maker System initialized (6 products, 4 buildings)") end
function GlassBenchMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassBenchMaker.maker={name=n or ("Mizar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mizar najet: %s (spretnost: %d)",GlassBenchMaker.maker.name,s),"success") end; return true end
function GlassBenchMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassBenchMaker.build(id) local ok,e=GlassBenchMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassBenchMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassBenchMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassBenchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassBenchMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassBenchMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassBenchMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassBenchMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassBenchMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassBenchMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassBenchMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassBenchMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassBenchMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassBenchMaker.buildings==0 then return false,"Potrebna mizarska delavnica" end; if not GlassBenchMaker.maker then return false,"Potreben mizar" end; return true end
function GlassBenchMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassBenchMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassBenchMaker.ironStock=GlassBenchMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassBenchMaker.bronzeStock=GlassBenchMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassBenchMaker.woodStock=GlassBenchMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassBenchMaker.leatherStock=GlassBenchMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassBenchMaker.silverStock=GlassBenchMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassBenchMaker.goldStock=GlassBenchMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassBenchMaker.jewelStock=GlassBenchMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassBenchMaker.pearlStock=GlassBenchMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassBenchMaker.maker then t=math.max(1,t-math.floor(GlassBenchMaker.maker.skill/13)) end; table.insert(GlassBenchMaker.activeMaking,{id="glassbench_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassBenchMaker.completeMaking(m) local q=1.0+(GlassBenchMaker.getQualityBonus()/100); if GlassBenchMaker.maker then q=q+(GlassBenchMaker.maker.skill/140) end; q=math.min(2.5,q); GlassBenchMaker.productStock[m.productType]=(GlassBenchMaker.productStock[m.productType] or 0)+m.quantity; GlassBenchMaker.totalProducts=GlassBenchMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBenchMaker.maker then GlassBenchMaker.maker.itemsMade=GlassBenchMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBenchMaker.maker.skill=math.min(100,GlassBenchMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Miza izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassbench.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassBenchMaker.update(dt) if not _G.state then return end; GlassBenchMaker.dayTimer=GlassBenchMaker.dayTimer+dt; if GlassBenchMaker.dayTimer>=30 then GlassBenchMaker.dayTimer=0; for i=#GlassBenchMaker.activeMaking,1,-1 do local m=GlassBenchMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassBenchMaker.completeMaking(m); table.remove(GlassBenchMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassBenchMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassBenchMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassBenchMaker.getStats() return {ironStock=GlassBenchMaker.ironStock,bronzeStock=GlassBenchMaker.bronzeStock,woodStock=GlassBenchMaker.woodStock,leatherStock=GlassBenchMaker.leatherStock,silverStock=GlassBenchMaker.silverStock,goldStock=GlassBenchMaker.goldStock,jewelStock=GlassBenchMaker.jewelStock,pearlStock=GlassBenchMaker.pearlStock,productStock=GlassBenchMaker.productStock,numBuildings=#GlassBenchMaker.buildings,hasMaker=GlassBenchMaker.maker~=nil,makerName=GlassBenchMaker.maker and GlassBenchMaker.maker.name or "—",makerSkill=GlassBenchMaker.maker and GlassBenchMaker.maker.skill or 0,activeMaking=#GlassBenchMaker.activeMaking,totalProducts=GlassBenchMaker.totalProducts} end
return GlassBenchMaker
